@pytest.mark.parametrize("driver", ["coordinator", "main-loop"]) def test_B24_five_minutes_bad_identity_backoff_keeps_hold_and_allows_health_and_other_position(tmp_path, monkeypatch, driver): rig = Rig(tmp_path, protection=ProtectionConfig(enabled=True), risk_per_trade_pct=.0015) _two_open_positions(rig) rows = {row['symbol']: row for row in rig.store.protections()} bad = rows['AAPL']; good = rows['SPY'] original_open = rig.broker.open_orders position_truth = rig.broker.positions_fresh execution_truth = rig.broker.executions_today raw_orders = original_open() native = [_native_from_open(rig, order, wrong=order.symbol == 'AAPL') for order in raw_orders] adapter = IbkrBroker(rig.cfg); adapter.ib = NativeIB(rig.clock) adapter.ib.snapshot = native def native_positions(): return [SimpleNamespace(account=position.account, contract=SimpleNamespace(symbol=position.symbol, conId=position.con_id, secType='STK', currency='USD'), position=position.quantity, avgCost=position.avg_cost) for position in position_truth()] def native_executions(): return [SimpleNamespace( execution=SimpleNamespace(execId=fill.exec_id, acctNumber=rig.cfg.account, clientId=rig.cfg.client_id, orderRef=fill.intent_id, side='BOT' if fill.side == 'BUY' else 'SLD', shares=fill.quantity, price=fill.price, time=fill.time, orderId=fill.broker_order_id or 0, permId=fill.perm_id or 0), contract=SimpleNamespace(symbol=fill.symbol, conId=fill.con_id or rig.broker.con_ids[fill.symbol], secType='STK', currency='USD'), commissionReport=SimpleNamespace( execId=fill.exec_id if fill.commission is not None else '', commission=fill.commission)) for fill in execution_truth()] adapter.ib.positions_provider = native_positions adapter.ib.executions_provider = native_executions adapter.set_urgent_handler(rig.engine._on_urgent_broker_event) monkeypatch.setattr('v6lite.broker.ibkr.time.monotonic', lambda: rig.clock.now().timestamp()) # All fresh queries use the real adapter's guard and converters. Streamed # positions remains its cache path rather than Fake.positions re-querying. for method in ('open_orders', 'positions', 'positions_fresh', 'executions_today', 'account_executions_today'): monkeypatch.setattr(rig.broker, method, getattr(adapter, method)) # This native contradiction creates the actual UNKNOWN/hold/frozen state. adapter._on_status(next(trade for trade in native if trade.contract.symbol == 'AAPL')) assert rig.store.protection(bad['position_id'])['state'] == 'UNKNOWN' assert rig.store.intent(bad['intent_id'])['hold_reason'] and rig.store.control('frozen:AAPL') hold = rig.store.intent(bad['intent_id'])['hold_reason'] attempts = [] query_trace = adapter.ib.queries evidence = rig.engine._protection_evidence def traced(row): attempts.append((row['symbol'], rig.clock.now().timestamp())) return evidence(row) monkeypatch.setattr(rig.engine, '_protection_evidence', traced) heartbeats = [] heartbeat = rig.broker.gateway_heartbeat_request def healthy_request(): heartbeats.append(rig.clock.now().timestamp()) return heartbeat() monkeypatch.setattr(rig.broker, 'gateway_heartbeat_request', healthy_request) query_trace.clear(); rig.channel.messages.clear() writes = tuple(len(x) for x in (rig.broker.sent, rig.broker.sent_protections, rig.broker.modified_protections, rig.broker.cancels)) started = rig.clock.now().timestamp() # Real openOrders converts native orders and generates PriceObservation # events, reproducing the urgent-pending feedback that caused the storm. while rig.clock.now().timestamp() - started < 300: if driver == 'main-loop': rig.tick() # Real recovery/resolve/reconcile paths remain enabled. before_pump = rig.clock.now().timestamp() adapter.pump(1) if rig.clock.now().timestamp() - before_pump < .1: # A self-generated urgent wake must not stall virtual time; # this is CPU elapsed time, never a new broker confirmation. rig.advance(seconds=.1) else: rig.engine._protection_progress(rig.clock.now(), steady_budget=True, phase='active') rig.engine._protection_progress(rig.clock.now(), steady_budget=True, phase='steady') rig.engine._gateway_heartbeat(rig.clock.now()) row = rig.store.protection(bad['position_id']) assert row['state'] == 'UNKNOWN' and row['confirmed_remaining'] == bad['confirmed_remaining'] assert row['pending_max_remaining'] == bad['pending_max_remaining'] assert rig.store.intent(bad['intent_id'])['hold_reason'] == hold and rig.store.control('frozen:AAPL') rig.advance(seconds=.1) bad_times = [at for symbol, at in attempts if symbol == 'AAPL'] good_times = [at for symbol, at in attempts if symbol == 'SPY'] > assert 10 <= len(bad_times) <= 15, ('five-minute identity attempts', len(bad_times)) E AssertionError: ('five-minute identity attempts', 3000) E assert 3000 <= 15 E + where 3000 = len([1791295231.0, 1791295231.1, 1791295231.2, 1791295231.3, 1791295231.4, 1791295231.5, ...])
