@pytest.mark.parametrize('operation', ['reset', 'disconnect']) def test_B24_reset_or_disconnect_discards_queued_writes_and_old_timer_cannot_replay_on_reconnect( tmp_path, monkeypatch, request, operation): adapter, loop, messages = _native_wire(tmp_path, monkeypatch, request) client = adapter.ib.client # One old-socket query is actually sent and gets its own End. Keeping its # rate timestamp across reconnect avoids a channel burst after reset. client.reqPositions(); adapter.ib.wrapper.positionEnd() for n in range(client.MaxRequests - 1): client.sendMsg('49\0old-capacity-' + str(n) + '\0') client.sendMsg('3\0obsolete-place\0') client.sendMsg('4\0obsolete-cancel\0') timers = list(loop.queue) assert timers and len(client._msgQ) >= 2 assert not any('obsolete-' in message for _, message in messages) _invalidate(client, operation) _reconnect_without_network(adapter) start_of_new_generation = len(messages) assert adapter.positions_fresh() == [] _force_obsolete_timers(loop, timers) loop.drain() assert not any('obsolete-' in message for _, message in messages), messages position_times = [at for at, message in messages if _opcode(message) == '61'] assert len(position_times) == 2 > assert position_times[1] - position_times[0] >= 1 - 1e-6, position_times E AssertionError: [1.000001, 1.000001] E assert (1.000001 - 1.000001) >= (1 - 1e-06)
