@pytest.mark.parametrize('operation', ['reset', 'disconnect']) def test_B24_reset_or_disconnect_inside_conn_send_aborts_old_drain_before_remaining_writes( tmp_path, monkeypatch, request, operation): adapter, loop, messages = _native_wire(tmp_path, monkeypatch, request) client = adapter.ib.client for n in range(client.MaxRequests): client.sendMsg('49\0old-capacity-' + str(n) + '\0') client.sendMsg('3\0old-place-one\0') client.sendMsg('4\0old-cancel-two\0') client.sendMsg('3\0old-place-three\0') timers = list(loop.queue) assert timers and len(client._msgQ) == 3 assert not any(_opcode(message) in {'3', '4'} for _, message in messages) reset_count = [] def transport(packet): message = packet[4:].decode() messages.append((loop.time(), message)) if message == '3\0old-place-one\0': reset_count.append(operation) # Actual native lifecycle reset while sendMsg still owns local # deque references; the drain must notice the changed generation. _invalidate(client, operation) # A new generation may become ready while the old drain still # owns its stack. Its valid protection must drain automatically, # without resurrecting old messages or needing an external kick. _reconnect_without_network(adapter) client.sendMsg('3\0new-generation-stop\0') monkeypatch.setattr(client.conn, 'sendMsg', transport) loop.queue.clear() loop.now = 2.0 _force_obsolete_timers(loop, timers) loop.drain() sent_old_writes = [message for _, message in messages if _opcode(message) in {'3', '4'} and 'old-' in message] assert reset_count == [operation] > assert sent_old_writes == ['3\0old-place-one\0'], ('old deque continued after reset', sent_old_writes) E AssertionError: ('old deque continued after reset', ['3\x00old-place-one\x00', '4\x00old-cancel-two\x00', '3\x00old-place-three\x00']) E assert ['3\x00old-pl...ce-three\x00'] == ['3\x00old-place-one\x00'] E E Left contains 2 more items, first extra item: '4\x00old-cancel-two\x00' E Use -v to get more diff
